    @staticmethod
    def _at_or_after(observed: str, marker: str) -> bool:
        if not observed or not marker:
            return False
        try:
            def parse(value: str) -> datetime:
                normalized = value.strip().replace("Z", "+00:00")
                parsed = datetime.fromisoformat(normalized)
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                return parsed.astimezone(timezone.utc)
            return parse(observed) >= parse(marker)
        except ValueError:
            return False

    @staticmethod
    def _order_summary(order: Mapping[str, Any] | None) -> dict[str, Any] | None:
        if not isinstance(order, Mapping):
            return None
        address = order.get("address") if isinstance(order.get("address"), Mapping) else {}
        payment = order.get("payment") if isinstance(order.get("payment"), Mapping) else {}
        items = order.get("items") if isinstance(order.get("items"), list) else []
        return {
            "order_id": str(order.get("id") or ""),
            "created_at": str(order.get("createdAt") or ""),
            "note": str(order.get("note") or ""),
            "address_id": str(address.get("id") or ""),
            "payment_method_id": str(payment.get("id") or ""),
            "status": str(order.get("status") or ""),
            "total": order.get("total"),
            "items": [
                {
                    "item_id": str(item.get("id") or ""),
                    "product_id": str((item.get("product") or {}).get("id") or "") if isinstance(item.get("product"), Mapping) else "",
                    "title": str((item.get("product") or {}).get("title") or "") if isinstance(item.get("product"), Mapping) else "",
                    "quantity": item.get("quantity"),
                    "selected_spec": str(item.get("selectedSpec") or ""),
                }
                for item in items if isinstance(item, Mapping)
            ],
        }
